// A viem kit over the Hardhat node globalSetup starts: a public client, wallets from Hardhat's default mnemonic,
// deploys from the generated bytecode, payments and time warps.
import {
  kickbackAbi,
  kickbackBytecode,
  mockArbitrableProxyAbi,
  mockArbitrableProxyBytecode,
  mockKlerosLiquidAbi,
  mockKlerosLiquidBytecode,
} from "@kickback/contracts";
import {
  createPublicClient,
  createTestClient,
  createWalletClient,
  getAddress,
  http,
  keccak256,
  type Abi,
  type Address,
  type ContractConstructorArgs,
  type Hash,
  type Hex,
  type Transport,
} from "viem";
import { mnemonicToAccount } from "viem/accounts";
import { hardhat } from "viem/chains";
import { inject } from "vitest";

import type { KickbackDeployArgs } from "../src";

const MNEMONIC = "test test test test test test test test test test test junk";
/** Hardhat's default accounts (10,000 ETH each); 0 is the owner in these tests. */
export const accounts = Array.from({ length: 16 }, (_, i) => mnemonicToAccount(MNEMONIC, { addressIndex: i }));

export function chainKit(transport: Transport = http(inject("rpcUrl"))) {
  const rpcUrl = inject("rpcUrl");
  const client = createPublicClient({ chain: hardhat, transport, cacheTime: 0, pollingInterval: 50 });
  const testClient = createTestClient({ chain: hardhat, mode: "hardhat", transport: http(rpcUrl) });
  const wallets = accounts.map((account) => createWalletClient({ account, chain: hardhat, transport: http(rpcUrl) }));
  const wallet = (i: number) => wallets[i]!;
  const addr = (i: number): Address => accounts[i]!.address;

  const mined = async (hash: Hash) => {
    const r = await client.waitForTransactionReceipt({ hash, pollingInterval: 50 });
    if (r.status !== "success") throw new Error(`tx ${hash} reverted`);
    return r;
  };
  const deploy = async <const A extends Abi>(
    abi: A,
    bytecode: Hex,
    args: ContractConstructorArgs<A>,
    from = 0,
  ): Promise<Address> => {
    const hash = await wallet(from).deployContract({ abi, bytecode, args } as never);
    const r = await mined(hash);
    return getAddress(r.contractAddress!);
  };
  /** A plain ETH transfer (the usual way a guest pays); returns its hash. */
  const pay = async (from: number, to: Address, value: bigint): Promise<Hash> => {
    const hash = await wallet(from).sendTransaction({ to, value });
    await mined(hash);
    return hash;
  };
  /** A transaction that is mined but fails (an explicit gas limit skips the estimate that would refuse it). */
  const failedTx = async (from: number, to: Address, value: bigint, gas = 100_000n, data?: Hex): Promise<Hash> => {
    const w = wallet(from);
    const request = await w.prepareTransactionRequest({ to, value, gas, data });
    const signed = await w.account.signTransaction(request as never);
    const hash = keccak256(signed);
    try {
      await client.request({ method: "eth_sendRawTransaction", params: [signed] });
    } catch {
      // Hardhat answers a reverted transaction with an error, but mines it
    }
    const r = await client.waitForTransactionReceipt({ hash, pollingInterval: 50 });
    if (r.status !== "reverted") throw new Error(`tx ${hash} did not fail`);
    return hash;
  };
  /** Calls a kickback function from account `from` and waits for it. */
  const kick = async (
    address: Address,
    from: number,
    functionName: string,
    args: readonly unknown[] = [],
    value?: bigint,
  ) => {
    const hash = await wallet(from).writeContract({ address, abi: kickbackAbi, functionName, args, value } as never);
    return mined(hash);
  };
  const read = <T>(address: Address, functionName: string, args: readonly unknown[] = []): Promise<T> =>
    client.readContract({ address, abi: kickbackAbi, functionName, args } as never) as Promise<T>;
  const warp = async (seconds: number) => {
    await testClient.increaseTime({ seconds });
    await testClient.mine({ blocks: 1 });
  };
  const now = async () => Number((await client.getBlock()).timestamp);
  const balance = (a: Address) => client.getBalance({ address: a });

  const mocks = async () => {
    const liquid = await deploy(mockKlerosLiquidAbi, mockKlerosLiquidBytecode, []);
    const proxy = await deploy(mockArbitrableProxyAbi, mockArbitrableProxyBytecode, [liquid]);
    return { liquid, proxy };
  };
  const deployKickback = (args: ContractConstructorArgs<typeof kickbackAbi> | KickbackDeployArgs, from = 0) =>
    deploy(kickbackAbi, kickbackBytecode, args as ContractConstructorArgs<typeof kickbackAbi>, from);

  return {
    rpcUrl,
    client,
    testClient,
    wallet,
    addr,
    mined,
    deploy,
    pay,
    failedTx,
    kick,
    read,
    warp,
    now,
    balance,
    mocks,
    deployKickback,
  };
}
export type ChainKit = ReturnType<typeof chainKit>;
